targets.query:
import "dict"

names = dict.fromList(pairs: [
    {key: "BalancingEnable", value: "Balancing allowed"},
    {key: "BalancingActive", value: "Balancing now"}
])
order = dict.fromList(pairs: [
    {key: "BalancingEnable", value: 0},
    {key: "BalancingActive", value: 1}
])

// 1 = ON, 0 = OFF (allowed); 3 = ACTIVE, 2 = IDLE (balancing now)
from(bucket: "CAN_prod")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => (r["_measurement"] == "MST" and r["_field"] == "BalancingEnable")
      or (r["_measurement"] == "MST" and r["_field"] == "BalancingActive"))
  |> filter(fn: (r) => "${car}" == "All" or r["car"] == "${car}")
  |> last()
  |> toFloat()
  |> group()
  |> map(fn: (r) => ({
      Name: dict.get(dict: names, key: r._field, default: r._field),
      o: dict.get(dict: order, key: r._field, default: 99),
      _value: if r._field == "BalancingActive" then (if r._value > 0.5 then 3.0 else 2.0)
              else (if r._value > 0.5 then 1.0 else 0.0)}))
  |> sort(columns: ["o"])
  |> keep(columns: ["Name", "_value"])
